<?php

namespace App\Services\SiteAudit;

/**
 * Подсказки к отчётам: что это / почему плохо / как исправить.
 */
class SiteAuditFindingHelp
{
    /**
     * @return array{what:string,why:string,fix:string}
     */
    public static function forCode(string $code, array $meta = []): array
    {
        $map = self::map();
        if (isset($map[$code])) {
            return self::normalize($map[$code], $meta);
        }

        return self::normalize([], $meta);
    }

    /**
     * Короткая подсказка по тексту ошибки HTML (libxml / эвристики).
     */
    public static function htmlErrorHint(string $message): ?string
    {
        $m = mb_strtolower(trim($message));
        if ($m === '') {
            return null;
        }

        $rules = [
            [
                'match' => 'error parsing attribute name',
                'tip' => 'Частый баг: после значения атрибута лишняя «;» внутри тега, например src="…svg"; title="…". W3C пишет это как «Attribute “;” not allowed» / «No space between attributes». Уберите точку с запятой между атрибутами.',
            ],
            [
                'match' => 'error parsing attribute value',
                'tip' => 'Значение атрибута оборвано или без закрывающей кавычки. Проверьте шаблон: не режется ли HTML посередине атрибута.',
            ],
            [
                'match' => 'no space between attributes',
                'tip' => 'Между атрибутами нет пробела или торчит лишний символ (часто «;» после кавычки: src="…"; title=…).',
            ],
            [
                'match' => 'attribute “;” not allowed',
                'tip' => 'В теге лишняя «;» между атрибутами (типично после src="…";). Уберите её — атрибут «;» не существует.',
            ],
            [
                'match' => 'attribute ";" not allowed',
                'tip' => 'В теге лишняя «;» между атрибутами (типично после src="…";). Уберите её — атрибут «;» не существует.',
            ],
            [
                'match' => 'opening and ending tag mismatch',
                'tip' => 'Теги закрыты не в том порядке (например </div></a> вместо </a></div>). Часто ломает меню/карточки в общем шаблоне.',
            ],
            [
                'match' => 'unexpected end tag',
                'tip' => 'Лишний закрывающий тег без пары. Проверьте include’ы шаблона — не закрывается ли блок дважды.',
            ],
            [
                'match' => 'tag ',
                'tip' => 'Сообщение libxml «Tag … invalid»: часто HTML5/SVG (details, summary, circle, rect…), которые парсер не знает по таблице HTML4. Если тег внутри <svg> или это FAQ на <details>/<summary> — ломать разметку не нужно; чините только реально битые теги (лишние </p>, «;» между атрибутами и т.п.). В режиме HTML5 (Nu) такие ложные срабатывания не появляются.',
            ],
            [
                'match' => 'premature end of data',
                'tip' => 'HTML оборван: страница обрезана по размеру/таймауту или шаблон упал на середине вывода.',
            ],
            [
                'match' => 'незакрытый html-комментарий',
                'tip' => 'Есть <!-- без -->. Часто забытый отладочный комментарий в шаблоне «съедает» кусок страницы.',
            ],
            [
                'match' => 'несколько закрывающих тегов </html>',
                'tip' => 'В ответе больше одного </html> — подмешивается второй документ (виджет, ошибка include, чужой футер).',
            ],
            [
                'match' => 'несколько закрывающих тегов </body>',
                'tip' => 'В ответе больше одного </body> — обычно два шаблона склеены в один ответ.',
            ],
            [
                'match' => 'entity',
                'tip' => 'Кривая HTML-entity (& без ; или & в тексте). В тексте пишите &amp;, либо экранируйте вывод.',
            ],
        ];

        foreach ($rules as $rule) {
            if (mb_strpos($m, $rule['match']) !== false) {
                return $rule['tip'];
            }
        }

        return 'Откройте исходный код страницы, найдите указанную строку (если есть) и поправьте разметку в шаблоне. Клик по тексту ошибки — поиск в Google.';
    }

    /**
     * @param  array<string, mixed>  $row
     * @param  array<string, mixed>  $meta
     * @return array{what:string,why:string,fix:string}
     */
    private static function normalize(array $row, array $meta = []): array
    {
        $desc = trim((string) ($meta['description'] ?? ''));
        $fix = $row['fix'] ?? $row['how'] ?? null;

        return [
            'what' => (string) ($row['what'] ?? ($desc !== '' ? $desc : 'Проверка технического аудита по этому отчёту.')),
            'why' => (string) ($row['why'] ?? 'Может влиять на индексацию, сниппеты или удобство обхода сайта.'),
            'fix' => (string) ($fix ?? 'Разберите URL из списка, устраните причину и перезапустите проверку.'),
        ];
    }

